class TokenBucket {
  constructor(capacity, refillRate) { // refillRate: 每秒补充令牌数
    this.capacity = capacity;
    this.refillRate = refillRate;
    this.tokens = capacity;
    this.lastRefill = Date.now();
  }

  refill() {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    if (elapsed > 0) {
      this.tokens = Math.min(this.capacity, this.tokens + elapsed * this.refillRate);
      this.lastRefill = now;
    }
  }

  tryAcquire(tokens = 1) {
    this.refill();
    if (this.tokens >= tokens) {
      this.tokens -= tokens;
      return true;
    }
    return false;
  }
}

class SlidingWindowLog {
  constructor(windowMs, maxRequests) {
    this.windowMs = windowMs;
    this.maxRequests = maxRequests;
    this.log = []; // 请求时间戳
  }

  tryAcquire(now = Date.now()) {
    const boundary = now - this.windowMs;
    while (this.log.length && this.log[0] <= boundary) this.log.shift(); // 清理过期请求
    if (this.log.length >= this.maxRequests) return false;
    this.log.push(now);
    return true;
  }
}

// 测试 1：令牌桶容量 5、每秒补 2 个
const tb = new TokenBucket(5, 2);
const r1 = Array.from({ length: 7 }, () => tb.tryAcquire());
console.log('令牌桶瞬时 7 次请求:', r1); // 前 5 次 true，后 2 次 false

// 测试 2：等待 1 秒后应补充约 2 个令牌
setTimeout(() => {
  console.log('1 秒后连续请求 3 次:', [tb.tryAcquire(), tb.tryAcquire(), tb.tryAcquire()]); // true true false

  // 测试 3：滑动窗口 1 秒内最多 5 次
  const sw = new SlidingWindowLog(1000, 5);
  const r2 = Array.from({ length: 7 }, (_, i) => sw.tryAcquire(1000 + i * 10));
  console.log('滑动窗口瞬时 7 次请求:', r2); // 前 5 次 true，后 2 次 false
  // 1.1 秒后旧请求全部滑出窗口
  console.log('窗口滑动后请求:', sw.tryAcquire(2200)); // true
}, 1000);
